select c.id,'Object '||n||' — '||c.name,lower(c.slug||'-object-'||n),'Designed with restraint and made to last. Honest materials, thoughtful details.','Quietly functional. Intentionally made.',(35+n*17)::numeric,case when n%4=0 then (55+n*19)::numeric else null end,case when n%11=0 then 0 else 4+n end,'https://images.unsplash.com/photo-1524758631624-e2822e304c36?auto=format&fit=crop&w=1000&q=80',n<=6 from generate_series(1,30)n join public.categories c on c.id=('00000000-0000-4000-8000-'||lpad((((n-1)%5)+1)::text,12,'0'))::uuid on conflict(slug)do nothing;
